from rest_framework import viewsets, filters, status
from rest_framework.decorators import action
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticatedOrReadOnly, IsAuthenticated
from django_filters.rest_framework import DjangoFilterBackend
from django.db.models import Avg, Count

from .models import Book, Favorite
from .serializers import (
    BookListSerializer, BookDetailSerializer, BookWriteSerializer,
)
from .permissions import IsOwnerOrReadOnly
from .pagination import StandardPagination
from .filters import BookFilter


class BookViewSet(viewsets.ModelViewSet):
    permission_classes = [IsAuthenticatedOrReadOnly, IsOwnerOrReadOnly]
    pagination_class = StandardPagination
    filter_backends = [DjangoFilterBackend, filters.SearchFilter, filters.OrderingFilter]
    filterset_class = BookFilter
    search_fields = ["title", "description", "author__full_name"]
    ordering_fields = ["price", "published_at", "title"]
    ordering = ["-created_at"]
    lookup_field = "slug"

    def get_queryset(self):
        return (
            Book.objects
            .select_related("author", "category")
            .prefetch_related("categories")
            .annotate(
                reviews_count=Count("reviews"),
                average_rating=Avg("reviews__rating"),
            )
        )

    def get_serializer_class(self):
        if self.action == "list":
            return BookListSerializer
        if self.action in ("create", "update", "partial_update"):
            return BookWriteSerializer
        return BookDetailSerializer

    def perform_create(self, serializer):
        serializer.save(owner=self.request.user)

    @action(detail=False, methods=["get"])
    def top_rated(self, request):
        """کتاب‌های با میانگین امتیاز بالای ۴."""
        books = (
            self.filter_queryset(self.get_queryset())
            .filter(average_rating__gte=4)
            .order_by("-average_rating")[:10]
        )
        serializer = self.get_serializer(books, many=True)
        return Response(serializer.data)

    @action(detail=True, methods=["post", "delete"], permission_classes=[IsAuthenticated])
    def favorite(self, request, slug=None):
        """Toggle علاقه‌مندی کتاب."""
        book = self.get_object()
        favorite, created = Favorite.objects.get_or_create(
            user=request.user, book=book,
        )
        if not created:
            favorite.delete()
            return Response({"favorited": False})
        return Response({"favorited": True}, status=status.HTTP_201_CREATED)

